'use strict';
const $=s=>document.querySelector(s);let session=null,state=null,receivedAt=0,serverAge=0,lastOK=0,polling=false,ready=false,pending=new Map(),confirmed=null,confirmedAt=0,outbox=[],sending=false,holding=false,buzzSeq=0,buzzTimer=null,wake=null;
let direct=null,directSignalID=null,lastDirect=0,lastPoll=0,directRTT=0;
function directFresh(){return direct?.open&&Date.now()-lastDirect<1500}
function closeDirect(){direct?.close();direct=null;directSignalID=null;lastDirect=0}
async function connectDirect(signal){if(!signal||signal.id===directSignalID||!window.RTCPeerConnection)return;closeDirect();directSignalID=signal.id;const current=session;const link=new CourtDirectLink({onMessage:m=>{if(session!==current||direct!==link)return;lastDirect=Date.now();if(m.kind==='pong'&&Number.isFinite(m.at))directRTT=Math.max(0,performance.now()-m.at);if(m.kind==='state'){lastOK=Date.now();for(const id of m.ack||[])pending.delete(id);for(const [id,p] of pending)if(p.game!==m.state?.id||m.state?.status==='종료'||Date.now()-p.when>4500){pending.delete(id);note('확인이 지연되거나 경기가 변경되어 메인 현황으로 복구했습니다.')}confirmed=m.state;confirmedAt=performance.now()-Math.min(100,directRTT/2);ready=!!confirmed;reconcile();connected(ready,'● 직접 연결'+(directRTT?' · '+Math.round(directRTT)+'ms':''));if(pending.size)note(`입력 반영 · 메인 확인 중 ${pending.size}`);else if(!/복구|불확실|취소/.test($('#commandStatus').textContent))note('메인 점수판과 직접 연결됨')}},onClose:()=>{lastDirect=0}});direct=link;try{const answer=await link.answer(signal.offer);if(session===current&&direct===link)await api(current.code+'/answer',{id:signal.id,answer},current.token)}catch{if(direct===link)closeDirect()}}
setInterval(()=>{if(direct?.open)direct.send({kind:'ping',at:performance.now()})},500);
const keys={KeyQ:'14',KeyW:'reset',KeyE:'shot',KeyR:'adjust:shot:1000',KeyF:'adjust:shot:-1000',KeyU:'adjust:clock:60000',KeyJ:'adjust:clock:-60000',KeyI:'adjust:clock:1000',KeyK:'adjust:clock:-1000',KeyO:'toggle',KeyA:'score:0:1',KeyS:'score:0:2',KeyD:'score:0:3',KeyZ:'score:0:-1',KeyX:'foul:0:1',KeyC:'timeout:0',Quote:'score:1:1',Semicolon:'score:1:2',KeyL:'score:1:3',Slash:'score:1:-1',Period:'foul:1:1',Comma:'timeout:1',KeyN:'period',ArrowLeft:'poss:1',ArrowRight:'poss:2'};
async function api(path,body={},token=session?.token){const r=await fetch((window.COURTBOARD_RELAY_URL?window.COURTBOARD_RELAY_URL.replace(/\/$/,'')+'/':'./')+'api/remote/'+path,{method:'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify(body),signal:AbortSignal.timeout(3500),cache:'no-store'});let d;try{d=await r.json()}catch{throw Error('무선 서버 주소에서 컨트롤러를 열어주세요.')}if(!r.ok){const e=Error(d.error||'연결 오류');e.status=r.status;throw e}return d}
function connected(ok,message){ready=ok;$('#connection').textContent=message;document.querySelectorAll('[data-action],#horn').forEach(b=>{b.disabled=!ok||!state||state.status==='종료'||(state.mode==='3'&&(b.classList.contains('three')||b.dataset.action==='14'))||(/^timeout:/.test(b.dataset.action||'')&&state.timeouts[+b.dataset.action.split(':')[1]]>=state.limit)});if(!ok&&holding)stopHold()}
function note(t){$('#commandStatus').textContent=t}
function advance(g,ms){if(g.running)g.clock=Math.max(0,g.clock-ms);if(g.shotRunning)g.shot=Math.max(0,g.shot-ms)}
function predictAction(g,action){const [kind,i,n]=action.split(':');if(kind==='undo'){if(g.undoPreview){const previous=g.undoPreview;Object.assign(g,previous,{running:false,shotRunning:false,undoPreview:previous.undoPreview||null})}return}const previous=structuredClone(g);g.undoPreview=previous;switch(kind){case 'score':g.score[+i]=Math.max(0,g.score[+i]+Number(n));break;case 'foul':g.fouls[+i]=Math.max(0,g.fouls[+i]+Number(n));break;case 'timeout':g.timeouts[+i]=Math.min(g.limit,g.timeouts[+i]+1);break;case 'toMinus':g.timeouts[+i]=Math.max(0,g.timeouts[+i]-1);break;case 'toggle':g.running=!g.running&&(g.clock>0||(g.mode==='3'&&g.period>g.periods));break;case 'shot':g.shotRunning=!g.shotRunning&&g.shot>0;break;case 'reset':case '14':g.shot=kind==='14'?14000:g.mode==='3'?12000:24000;g.shotRunning=false;break;case 'adjust':g[i]=Math.max(0,g[i]+Number(n));if(g[i]===0){if(i==='clock')g.running=false;else g.shotRunning=false}break;case 'pos':g.pos=g.pos===1?2:1;break;case 'poss':g.pos=Number(i);break;case 'period':{const oldGroup=g.mode==='3'?'3':g.period>g.periods?'ot'+g.period:g.period<=2?'first':'second';g.period++;const group=g.mode==='3'?'3':g.period>g.periods?'ot'+g.period:g.period<=2?'first':'second';if(group!==oldGroup)g.timeouts=[0,0];g.limit=g.mode==='3'||g.period>g.periods?1:g.period<=2?2:3;if(g.mode!=='3'&&g.period<=g.periods)g.fouls=[0,0];g.clock=g.period>g.periods?(g.mode==='3'?0:g.otMinutes*60000):g.minutes*60000;g.shot=g.mode==='3'?12000:24000;g.running=g.shotRunning=false;break;}}}
function reconcile(){if(!confirmed)return;const now=performance.now();state=structuredClone(confirmed);let cursor=confirmedAt;for(const p of pending.values()){if(p.game!==state.id||state.status==='종료')continue;const at=Math.max(cursor,p.localAt);advance(state,Math.max(0,at-cursor));predictAction(state,p.action);cursor=at}advance(state,Math.max(0,now-cursor));receivedAt=now;serverAge=0;render();document.querySelector('.live').classList.toggle('awaiting',pending.size>0);connected(ready,$('#connection').textContent)}
function values(){if(!state)return;const elapsed=performance.now()-receivedAt+serverAge;const clock=Math.max(0,state.clock-(state.running?elapsed:0)),shot=Math.max(0,state.shot-(state.shotRunning?elapsed:0));const ct=state.mode==='3'&&state.period>state.periods?'--:--':clock<60000?(clock/1000).toFixed(1):`${String(Math.floor(Math.ceil(clock/1000)/60)).padStart(2,'0')}:${String(Math.ceil(clock/1000)%60).padStart(2,'0')}`;$('#liveClock').textContent=$('#gameMini').textContent=ct;$('#shotMini').textContent=$('#liveShot').textContent=shot<=10000?(shot/1000).toFixed(1):Math.ceil(shot/1000)}
function render(){if(!state)return;$('#match').textContent=state.tournament;$('#livePeriod').textContent=state.period>state.periods?'OT '+(state.period-state.periods):state.mode==='3'?'3 × 3':state.period+' QUARTER';for(const [side,i] of [['home',0],['away',1]]){$('#'+side+'Name').textContent=$('#'+side+'Title').textContent=i?state.b:state.a;$('#'+side+'Score').textContent=state.score[i];$('#'+side+'Meta').textContent=`파울 ${state.fouls[i]} · 타임아웃 ${state.timeouts[i]} / ${state.limit}`}
 $('#livePossession').textContent=state.pos===1?'◀':state.pos===2?'▶':'';$('#liveStatus').textContent=state.status==='종료'?'경기 종료':`경기 ${state.running?'진행':'정지'} · 샷 ${state.shotRunning?'진행':'정지'}`;
 $('#shotToggle').innerHTML=(state.shotRunning?'Ⅱ 정지':'▶ 시작')+' <kbd>E</kbd>';$('#gameToggle').innerHTML=(state.running?'Ⅱ 정지':'▶ 시작')+' <kbd>O</kbd>';$('#resetShot').innerHTML=(state.mode==='3'?'12초':'24초')+' <kbd>W</kbd>';values()}
async function poll(){if(!session||polling)return;if(directFresh()&&Date.now()-lastPoll<1000)return;lastPoll=Date.now();polling=true;const current=session,started=performance.now();try{const d=await api(current.code+'/poll',{},current.token);if(session!==current)return;lastOK=Date.now();if(d.status==='pending'){connected(false,'메인 승인 대기');$('#pairMessage').textContent='메인 점수판에서 연결을 승인해주세요.';return}
 connectDirect(d.signal);if(directFresh()){connected(true,'● 직접 연결'+(directRTT?' · '+Math.round(directRTT)+'ms':''));return}
 $('#pair').hidden=true;$('#console').hidden=false;$('#disconnect').hidden=false;
 for(const id of d.ack)pending.delete(id);
 for(const [id,p] of pending){if(p.game!==d.state?.id||d.state?.status==='종료'||Date.now()-p.when>4500){pending.delete(id);note('확인이 지연되거나 경기가 변경되어 메인 현황으로 복구했습니다.')}}
 confirmed=d.state;confirmedAt=performance.now()-Math.max(0,d.now-d.updatedAt)-(performance.now()-started)/2;
 ready=d.now-d.hostSeen<2500&&!!confirmed;reconcile();connected(ready,ready?'● 서버 중계 연결':'메인 연결 끊김 · 조작 중지');
 if(pending.size)note(`입력 반영 · 메인 확인 중 ${pending.size}`);else if(!/복구|불확실|취소/.test($('#commandStatus').textContent))note('메인 점수판과 연결됨');

 }catch(e){if(session!==current)return;if(!directFresh())connected(false,'연결 끊김 · 재접속 중');if([403,404,410].includes(e.status)){closeDirect();connected(false,'연결 해제됨');session=null;sessionStorage.removeItem('courtboard-controller');$('#pair').hidden=false;$('#console').hidden=true;$('#pairMessage').textContent=e.message;$('#pairForm button').disabled=false;$('#disconnect').hidden=true}}finally{polling=false}}
function command(action){if(!ready||!state)return;if(state.status==='종료')return;if(action.startsWith('timeout:')&&state.timeouts[+action.split(':')[1]]>=state.limit)return;if(action==='period'&&!confirm('다음 쿼터 / 연장으로 이동할까요?'))return;if(action==='undo'&&!confirm('직전 조작을 취소할까요? 두 시계는 정지됩니다.'))return;if(pending.size>=20){note('입력 확인 중입니다. 잠시 기다려주세요.');return}
 const id=crypto.randomUUID(),p={id,game:state.id,action,when:Date.now(),localAt:performance.now(),session};pending.set(id,p);reconcile();note(`입력 반영 · 메인 확인 중 ${pending.size}`);if(directFresh()&&direct.send({kind:'cmd',id,game:p.game,action})){setTimeout(()=>{if(pending.has(id)&&session===p.session){outbox.push(p);flush()}},700)}else{outbox.push(p);queueMicrotask(flush)}
}
async function flush(){if(sending)return;sending=true;try{while(outbox.length){const items=outbox.splice(0,20),current=session,valid=items.filter(p=>p.session===current&&ready&&Date.now()-p.when<1500&&pending.has(p.id));for(const p of items)if(!valid.includes(p))pending.delete(p.id);if(valid.length<items.length){reconcile();note('전송 지연으로 일부 입력을 취소했습니다. 메인 현황을 확인하세요.')}if(!valid.length){reconcile();note('전송하지 못한 입력을 취소했습니다. 메인 현황을 확인하세요.');continue}try{await api(current.code+'/commands',{commands:valid.map(({id,game,action})=>({id,game,action}))},current.token);poll()}catch(e){for(const p of valid)pending.delete(p.id);for(const p of outbox)pending.delete(p.id);outbox=[];reconcile();note('전송 결과가 불확실합니다. 메인 현황을 확인해주세요.');connected(false,'연결 확인 중')}}}finally{sending=false}}
async function buzz(active){if(!session)return;const current=session,seq=++buzzSeq;if(directFresh()&&direct.send({kind:'buzz',active,seq}))return;try{await api(current.code+'/buzz',{active,seq},current.token)}catch{if(active)stopHold()}}
function startHold(){if(holding||!ready)return;holding=true;$('#horn').classList.add('held');buzz(true);buzzTimer=setInterval(()=>{if(holding&&ready)buzz(true);else stopHold()},500)}
function stopHold(){const was=holding;holding=false;$('#horn').classList.remove('held');clearInterval(buzzTimer);if(was)buzz(false)}
$('#pairForm').onsubmit=async e=>{e.preventDefault();$('#pairForm button').disabled=true;try{const code=$('#code').value.trim(),d=await api(code+'/join',{name:$('#deviceName').value},null);session={code,token:d.token};buzzSeq=Date.now();sessionStorage.setItem('courtboard-controller',JSON.stringify(session));$('#disconnect').hidden=false;$('#pairMessage').textContent='메인 점수판에서 승인해주세요.';poll()}catch(e){$('#pairMessage').textContent=e.message;$('#pairForm button').disabled=false}};
$('#disconnect').onclick=async()=>{stopHold();const old=session;closeDirect();session=null;sessionStorage.removeItem('courtboard-controller');pending.clear();outbox=[];confirmed=null;state=null;connected(false,'연결 안 됨');$('#pair').hidden=false;$('#console').hidden=true;$('#disconnect').hidden=true;$('#pairMessage').textContent='연결을 해제했습니다.';$('#pairForm button').disabled=false;if(old)try{await api(old.code+'/leave',{},old.token)}catch{}};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)command(b.dataset.action)});
document.addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.metaKey||e.altKey||$('#helpDialog').open||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(e.code==='KeyH'){e.preventDefault();startHold();return}if(keys[e.code]){e.preventDefault();if(state?.mode==='3'&&['KeyQ','KeyD','KeyL'].includes(e.code))return;command(keys[e.code])}});
document.addEventListener('keyup',e=>{if(e.code==='KeyH')stopHold()});$('#horn').onpointerdown=e=>{e.preventDefault();$('#horn').setPointerCapture(e.pointerId);startHold()};$('#horn').onpointerup=stopHold;$('#horn').onpointercancel=stopHold;$('#horn').onlostpointercapture=stopHold;window.addEventListener('blur',stopHold);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopHold();else{poll();keepAwake()}});
async function keepAwake(){try{wake=await navigator.wakeLock?.request('screen')}catch{}}
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement){await document.exitFullscreen();return}if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else note('이 브라우저는 전체화면을 지원하지 않습니다. 홈 화면에 추가해 실행하세요.');await keepAwake()}catch{note('전체화면을 사용할 수 없습니다. 가로 화면으로 사용해주세요.')}};
$('#compact').onclick=()=>{document.body.classList.toggle('compact');$('#compact').textContent=document.body.classList.contains('compact')?'기본 크기':'컴팩트'};$('#help').onclick=()=>$('#helpDialog').showModal();$('#closeHelp').onclick=()=>$('#helpDialog').close();
try{session=JSON.parse(sessionStorage.getItem('courtboard-controller'));buzzSeq=Date.now()}catch{}if(session){$('#disconnect').hidden=false;$('#pairForm button').disabled=true;poll()}connected(false,'연결 안 됨');setInterval(poll,400);setInterval(()=>{values();if(ready&&!directFresh()&&Date.now()-lastOK>3000)connected(false,'연결 끊김 · 조작 중지')},50);
